import {
  CROUCH_SPEED,
  FLY_SPEED,
  GRAVITY,
  JUMP_VELOCITY,
  PLAYER_HALF_WIDTH,
  PLAYER_HEIGHT,
  SPRINT_MIN_HUNGER,
  SPRINT_SPEED,
  WALK_SPEED,
  WORLD_BORDER_PADDING
