      player.position[axis] += step;
      if (collidesAt(world, player.position, PLAYER_HALF_WIDTH, PLAYER_HEIGHT)) {
        player.position[axis] -= step;
        if (axis === "y" && step < 0) player.onGround = true;
        if (axis === "y") player.velocity.y = 0;
        break;
      }
      remaining -= step;
    }
  };

