    move.forward = pressed.has("KeyW");
    move.back = pressed.has("KeyS");
    move.left = pressed.has("KeyA");
    move.right = pressed.has("KeyD");
    move.jump = pressed.has("Space");
    move.crouch = pressed.has("KeyC");
