      if (engine.state.paused) engine.dispatch({ type: "resume" });
      else if (engine.state.inventoryOpen) engine.dispatch({ type: "toggleInventory" });
      else if (engine.state.advancementsOpen) engine.dispatch({ type: "toggleAdvancements" });
